import io
import os
import runpy
import sys
import unittest
from unittest.mock import patch

DESIRED = "498.75"
DESIRED2 = "Pay: 498.75"
STDIN = "45\n10.50\n"


def student_file():
    """PythonGrader uses student.py; Udemy coding exercises use exercise.py."""
    for name in ('student.py', 'exercise.py'):
        if os.path.isfile(name):
            return name
    return 'student.py'


def run_student(stdin=STDIN):
    output = io.StringIO()
    with patch('builtins.input', side_effect=_input_side_effect(stdin)):
        with patch('sys.stdout', output):
            try:
                runpy.run_path(student_file(), run_name='__main__')
            except SystemExit:
                pass
    return output.getvalue()


def _input_side_effect(stdin):
    lines = stdin.splitlines()
    # Preserve trailing blank semantics for programs that call input() once per line
    if stdin.endswith('\n'):
        # splitlines drops final empty; reconstruct queue of lines without newlines
        pass
    queue = list(lines)

    def _input(prompt=''):
        if not queue:
            raise EOFError('EOF when reading a line')
        return queue.pop(0)

    return _input


class OutputTests(unittest.TestCase):
    def test_desired_output(self):
        got = run_student().rstrip()
        # Normalize trailing whitespace per line for friendlier comparison
        got_norm = '\n'.join(line.rstrip() for line in got.splitlines()).rstrip()
        want = DESIRED.rstrip() if isinstance(DESIRED, str) else DESIRED
        alts = [want]
        if DESIRED2:
            alts.append(DESIRED2.rstrip())
        if got_norm not in alts:
            self.assertEqual(got_norm, want)


class SourceTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        with open(student_file(), encoding='utf-8') as f:
            cls.src = f.read()

    def test_source_input(self):
        self.assertIn("input", self.src,
            "You must prompt the pay and rate using the input() function.")

    def test_source_print(self):
        self.assertIn("print", self.src,
            "You must use the print function to print the output.")

    def test_source_if(self):
        self.assertIn("if", self.src,
            "You should use an if statement to decide to do the overtime computation or not.")

    def test_source_float(self):
        self.assertIn("float", self.src,
            "You should use the built-in float() function to convert from a string to a float.")

    def test_source_not_45(self):
        self.assertNotIn("45", self.src,
            "You must read the hours using input() and then convert it.")

    def test_source_not_10_5(self):
        self.assertNotIn("10.5", self.src,
            "You must read the rate using input() and then convert it.")

    def test_source_not_498(self):
        self.assertNotIn("498", self.src,
            "You must actually calculate the pay.")
